def add(p,key,title,stem,opts,why,correct=(0,),typ='conceptual',difficulty='easy',kind=None,locator=None,region=None,conflict=None,steps=None,formulas=None,assumptions=None):
 # Stable IDs, not display positions, bind every option explanation.
 k=len(b.questions)%4;opts=opts[k:]+opts[:k];correct=[(i-k)%4 for i in correct]
 q=b.add(p,key,title,stem,[x[0] for x in opts],correct,why,[x[1] for x in opts],typ=typ,difficulty=difficulty,conflict=conflict,steps=steps,formulas=formulas,assumptions=assumptions)
 q['options'].sort(key=lambda x:x['id'])
 for c in q['citations']:
  c['kind']=kind or ('figure' if typ=='diagram' else 'equation' if typ in ('numerical','derivation') else 'statement')
  c['locator']=f"Lecture 33, physical PDF page {c['physicalPage']}, printed footer {c['physicalPage']-986}: "+(locator or title)
  c['evidenceText']='Actual inspected pixels: '+NOTES[c['physicalPage']]+'\n'+c['evidenceText']
  if c['kind']=='figure':c['region']=region or {'x':.03,'y':.1,'width':.94,'height':.79}
 if conflict:
  pages=[p] if isinstance(p,int) else p
  q['conflictResolution'].update(sourceId='lectures',sourceSha256=SHA,physicalPages=pages)
  ISSUES.append({'questionId':q['id'],'physicalPages':pages,'sourceClaim':conflict,'qualification':why,'status':'explicitly qualified; not globally resolved'})
 return q
F_NORM=formula('r=R/S; g=G/S; b=B/S; S=R+G+B',{'R,G,B':'linear primary coefficients in the stated color-matching basis','S':'sum of the three coefficients','r,g,b':'normalized chromaticity coordinates'},{'R,G,B,S':'common intensity units','r,g,b':'dimensionless'},['S≠0; invariance discussed only for a common nonzero scale factor.'])
F_MOM=formula('m_pq=Σ_(u,v) u^p v^q X_uv; (u_c,v_c)=(m_10/m_00,m_01/m_00)',{'u,v':'horizontal and vertical pixel coordinates','p,q':'nonnegative integer moment powers','X_uv':'binary foreground weight at pixel (u,v)','m_pq':'raw spatial moment of order p+q','m_00':'nonzero foreground area/count','u_c,v_c':'centroid coordinates'},{'u,v,u_c,v_c':'pixel coordinates','X_uv':'dimensionless binary weight','m_pq':'pixel-coordinate units to power p+q, summed over pixels'},['Binary 0/1 mask and m_00>0.'])
F_CENT=formula('μ_20=m_20−m_10²/m_00; μ_02=m_02−m_01²/m_00; μ_11=m_11−m_10 m_01/m_00',{'m_pq':'raw moment Σu^p v^q X_uv','μ_pq':'central moment Σ(u−u_c)^p(v−v_c)^q X_uv','u_c,v_c':'centroid coordinates','u,v':'pixel coordinates','p,q':'nonnegative integer exponents','X_uv':'binary mask weight','m_00':'nonzero mask area'},{'μ_20,μ_02,μ_11':'squared pixel-coordinate units summed over pixels','u,v,u_c,v_c':'pixel coordinates','X_uv':'dimensionless'},['Nonempty binary mask; centroid definitions from raw moments.'])
F_ELL=formula('J=[[μ_20,μ_11],[μ_11,μ_02]]; a=2√(λ_1/m_00); b=2√(λ_2/m_00)',{'J':'displayed coordinate second-moment matrix','μ_20,μ_02,μ_11':'central spatial moments','λ_1,λ_2':'eigenvalues of J, ordered λ_1≥λ_2≥0','m_00':'nonzero region area','a,b':'major and minor semiaxis lengths of the equivalent filled ellipse'},{'a,b':'pixel-coordinate units','J,λ_1,λ_2':'area times squared pixel-coordinate units','m_00':'area units'},['Consistent continuous or discrete moment convention; major-axis direction is nonunique when eigenvalues coincide.'])
F_CIRC=formula('ρ=4πA/P²',{'ρ':'dimensionless circularity','A':'planar region area','P':'positive boundary perimeter','π':'circle constant'},{'A':'length²','P':'length','ρ,π':'dimensionless'},['Ideal Euclidean shape for exact circle/square results; digital estimators introduce error.'])
F_HOUGH=formula('ρ=u cosθ+v sinθ',{'ρ':'signed perpendicular offset from image origin','u,v':'image point coordinates','θ':'angle of the unit normal from the positive u-axis'},{'ρ,u,v':'pixels','θ':'radians'},['The selected angle domain and signed-offset convention are stated in each problem.'])
F_HARRIS=formula('C=det(A)−α tr(A)²; A=w*[[I_u²,I_u I_v],[I_u I_v,I_v²]]',{'C':'Harris corner response','A':'windowed gradient second-moment matrix','w':'spatial averaging window','*':'spatial convolution','I_u,I_v':'horizontal and vertical image intensity derivatives','α':'dimensionless sensitivity parameter','det(A)':'determinant','tr(A)':'trace'},{'I_u,I_v':'intensity per pixel','A':'squared gradient units for a normalized window','C':'fourth-power gradient units','α':'dimensionless'},['Consistent derivative and window normalization; numerical α is explicitly supplied.'])
